 const dict=lang==='en'?en:ja,walk=n=>{if(n.nodeType===3){let v=n.nodeValue;Object.entries(dict).sort((a,b)=>b[0].length-a[0].length).forEach(([a,b])=>v=v.replaceAll(a,b));n.nodeValue=v}else if(n.nodeType===1&&!['SCRIPT','STYLE'].includes(n.tagName))[...n.childNodes].forEach(walk)};walk(document.body);
